<script lang="ts">
import {untrack} from 'svelte';import Icon from './Icon.svelte';import {loadSelection,type HistoryRange,type SelectionSummary} from './bridge';import {stamp,observedDuration} from './statistics';import {daysForRows,piecesForDay,rowKey,rowState,states,clockText,zoomView,panView,tickStep,clusterMarkers,selectionForKeys,pruneSelection,isMarker,gestureView,type TimelineRow,type View} from './timeline';
let {rows,profile,selection,language,t}:{rows:TimelineRow[];profile:string;selection:HistoryRange;language:string;t:(key:string)=>string}=$props();
let root:HTMLElement;let board=$state<HTMLDivElement>();let width=$state(600);let view=$state<View>({start:0,end:1});let selected=$state<string[]>([]);let preview=$state<string[]>([]);let multi=$state(false);let legend=$state(false);let anchor=$state<string|null>(null);let summary=$state<SelectionSummary|null>(null);let summaryFailed=$state(false);let summaryLoading=$state(false);
let hovered=$state<string[]>([]);let skimmer=$state<number|null>(null);let hoverClock=$state('');let tooltip=$state('');let tooltipAt=$state({left:0,top:0});
interface Drag {mode:'pan'|'select';pointer:number;clientX:number;x:number;y:number;view:View;seed:string[];keys:string[];additive:boolean;shift:boolean;moved:boolean}
let drag=$state<Drag|null>(null);let gesture:{view:View;anchor:number}|null=null;
let days=$derived(daysForRows(rows,selection));let lanes=$derived(days.map(day=>({day,...piecesForDay(rows,day)})));let span=$derived(view.end-view.start);let active=$derived(new Set(drag?.mode==='select'&&drag.moved?preview:selected));
let ticks=$derived.by(()=>{const step=tickStep(span);const first=Math.ceil(view.start*86400/step)*step;const result=[];for(let second=first;second<=view.end*86400;second+=step)result.push({left:(second/86400-view.start)/span,label:clockText(second/86400).slice(0,5)});return result;});
let selectedRows=$derived(rows.filter(row=>selected.includes(rowKey(row))));
$effect(()=>{const available=new Set(rows.map(rowKey));untrack(()=>{const next=pruneSelection(selected,available);if(next.length!==selected.length)selected=next;});});
$effect(()=>{const id=profile;const range=selection;const keys=selected;let current=true;summary=null;summaryFailed=false;summaryLoading=keys.length>0;if(keys.length)loadSelection(id,range,keys).then(value=>{if(current)summary=value;}).catch(()=>{if(current)summaryFailed=true;}).finally(()=>{if(current)summaryLoading=false;});return()=>{current=false;};});
$effect(()=>{if(!board)return;const element=board;const observer=new ResizeObserver(()=>width=Math.max(1,element.clientWidth-56));observer.observe(element);width=Math.max(1,element.clientWidth-56);element.addEventListener('wheel',wheel,{passive:false});element.addEventListener('gesturestart',gestureStart,{passive:false});element.addEventListener('gesturechange',gestureChange,{passive:false});element.addEventListener('gestureend',gestureEnd,{passive:false});return()=>{observer.disconnect();element.removeEventListener('wheel',wheel);element.removeEventListener('gesturestart',gestureStart);element.removeEventListener('gesturechange',gestureChange);element.removeEventListener('gestureend',gestureEnd);gesture=null;};});
function clear(){selected=[];anchor=null;preview=[];}
function keysAt(target:EventTarget|null):string[]{const value=(target as Element|null)?.closest<HTMLElement>('[data-keys]')?.dataset.keys;return value?JSON.parse(value):[];}
function choose(keys:string[],additive=false,shift=false){const ordered=rows.filter(row=>!row.event||isMarker(row)).map(rowKey);selected=selectionForKeys(ordered,selected,keys,{additive,shift,anchor});anchor=keys[0]??null;}
function point(event:PointerEvent){const rect=board!.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(event.clientX-rect.left-56)/width)),y:Math.max(0,Math.min(lanes.length-1,Math.floor((event.clientY-rect.top)/46)))};}
function down(event:PointerEvent){if(event.button!==0||!board||event.clientX<board.getBoundingClientRect().left+56)return;const position=point(event);const keys=keysAt(event.target);event.preventDefault();board.focus({preventScroll:true});board.setPointerCapture(event.pointerId);drag={mode:event.altKey||!keys.length&&!multi?'pan':'select',pointer:event.pointerId,clientX:event.clientX,x:position.x,y:position.y,view:{...view},seed:event.ctrlKey||event.metaKey||multi?[...selected]:[],keys,additive:event.ctrlKey||event.metaKey||multi,shift:event.shiftKey,moved:false};preview=[];tooltip='';}
function move(event:PointerEvent){if(!board)return;const position=point(event);if(drag){if(Math.abs(event.clientX-drag.clientX)>4||position.y!==drag.y||drag.moved){drag.moved=true;if(drag.mode==='pan')view=panView(drag.view,-(event.clientX-drag.clientX)/width*(drag.view.end-drag.view.start));else{const left=view.start+Math.min(drag.x,position.x)*span;const right=view.start+Math.max(drag.x,position.x)*span;const chosen=[...drag.seed];for(let index=Math.min(drag.y,position.y);index<=Math.max(drag.y,position.y);index++){const lane=lanes[index];for(const piece of lane.clips)if(piece.right>=left&&piece.left<=right)chosen.push(rowKey(piece.row));for(const mark of lane.markers)if(mark.left>=left&&mark.left<=right)chosen.push(rowKey(mark.row));}preview=[...new Set(chosen)];}}return;}
 skimmer=position.x;hoverClock=clockText(view.start+position.x*span);hovered=keysAt(event.target);const matched=rows.filter(row=>hovered.includes(rowKey(row)));tooltip=matched.map(describe).join('\n\n');tooltipAt={left:Math.max(8,Math.min(event.clientX+12,window.innerWidth-330)),top:event.clientY>window.innerHeight-180?Math.max(8,event.clientY-180):event.clientY+18};}
function up(event:PointerEvent){if(!drag)return;const current=drag;drag=null;if(board?.hasPointerCapture(event.pointerId))board.releasePointerCapture(event.pointerId);if(current.moved){if(current.mode==='select')selected=preview;}else if(current.keys.length)choose(current.keys,current.additive,current.shift);else clear();preview=[];}
function wheel(event:WheelEvent){if(!board)return;if(gesture){event.preventDefault();return;}const rect=board.getBoundingClientRect();const at=view.start+Math.max(0,Math.min(1,(event.clientX-rect.left-56)/width))*span;const unit=event.deltaMode===1?16:event.deltaMode===2?width:1;const dx=event.deltaX*unit;const dy=event.deltaY*unit;if(event.ctrlKey){event.preventDefault();view=zoomView(view,Math.exp(dy*.005),at);}else if(Math.abs(dx)>Math.abs(dy)||event.shiftKey){event.preventDefault();view=panView(view,(dx||dy)/width*span);}}
function gestureStart(event:Event){event.preventDefault();const x=(event as Event&{clientX?:number}).clientX;const fraction=board&&typeof x==='number'?Math.max(0,Math.min(1,(x-board.getBoundingClientRect().left-56)/width)):skimmer??.5;gesture={view:{...view},anchor:view.start+fraction*span};}
function gestureChange(event:Event){event.preventDefault();if(gesture)view=gestureView(gesture.view,(event as Event&{scale:number}).scale,gesture.anchor);}
function gestureEnd(event:Event){event.preventDefault();gesture=null;}
function zoom(factor:number){view=zoomView(view,factor,view.start+(skimmer??.5)*span);}
function markerTypes(values:TimelineRow[]){const found=new Set<string>();return values.filter(row=>{const key=rowState(row).icon;if(found.has(key))return false;found.add(key);return true;});}
function bookingLines(row:TimelineRow){return (row.bookings??[]).flatMap(booking=>[booking.office,booking.address,...(booking.offers??[]).map(offer=>[offer.date,offer.time].filter(Boolean).join(' · '))]).filter(Boolean).join('\n');}
function describe(row:TimelineRow){return [t(rowState(row).label),stamp(row.start,language)+(row.event?'':' — '+stamp(row.end??row.last_seen,language)),typeof row.office_seen_at==='string'?t('Офисы')+': '+stamp(row.office_seen_at,language):'',typeof row.booking_seen_at==='string'?t('Выбор даты')+': '+stamp(row.booking_seen_at,language):'',row.restored?t('Восстановлено по журналам запуска'):'',bookingLines(row)||(row.offices??[]).join('\n')].filter(Boolean).join('\n');}
function keyboard(event:KeyboardEvent){if(event.key==='Escape'){clear();return;}if(event.target!==board)return;if(event.key==='+'||event.key==='='){event.preventDefault();zoom(.5);}else if(event.key==='-'){event.preventDefault();zoom(2);}else if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();view=panView(view,(event.key==='ArrowLeft'?-.1:.1)*span);}}
const metrics=[['checks','Проверок сит'],['actions_performed','Действий выполнено'],['pages_processed','Страниц обработано'],['offices_seen','Появлений офисов'],['booking_screens','Появления выбора даты'],['server_errors','Ошибок сервера'],['rate_limited','Ограничений HTTP 429'],['blocked','Ограничения доступа'],['flow_passes','Повторные проходы'],['browser_resets','Новая сессия']];
</script>
<svelte:window onpointerdown={event=>{if(!root?.contains(event.target as Node))clear();}}/>
<section class="timeline" bind:this={root}><div class="timeline-tools"><button class="flat legend-toggle" aria-expanded={legend} onclick={()=>legend=!legend}><span class="legend-dots"><i style:background={states.search.colour}></i><i style:background={states.cod.colour}></i><i style:background={states.recovery.colour}></i></span>{t('Легенда')}<Icon name="chevron-down" size={14}/></button><span class="tools-spacer"></span><button class="flat" aria-pressed={multi} class:chosen={multi} onclick={()=>multi=!multi}><Icon name="pointer" size={16}/>{t('Выбрать несколько')}</button><button class="icon-button" title={t('Приблизить')} aria-label={t('Приблизить')} onclick={()=>zoom(.5)}><Icon name="zoom_in"/></button><button class="icon-button" title={t('Отдалить')} aria-label={t('Отдалить')} onclick={()=>zoom(2)}><Icon name="zoom_out"/></button><button class="flat" onclick={()=>view={start:0,end:1}}>{t('Весь день')}</button></div>
{#if legend}<div class="timeline-legend">{#each Object.entries(states) as [key,state]}<span>{#if key==='restart'||key==='office'||key==='booking'}<Icon name={state.icon} size={15}/>{:else}<i class:gap={key==='gap'} style:background={state.colour}></i>{/if}{t(state.label)}</span>{/each}</div>{/if}
{#if !days.length}<p class="timeline-empty muted">{t('Нет наблюдений за выбранный период')}</p>{:else}
<div class="time-axis">{#each ticks as tick}<span style:left={`${tick.left*100}%`} class:first={tick.left===0} class:last={tick.left===1}>{tick.label}</span>{/each}</div>
<div class="timeline-board" role="grid" aria-label={t('История поиска')} tabindex="0" bind:this={board} onkeydown={keyboard} onpointerdown={down} onpointermove={move} onpointerup={up} onpointercancel={()=>{drag=null;preview=[];}} onpointerleave={()=>{if(!drag){hovered=[];skimmer=null;tooltip='';}}}>
{#each lanes as lane}<div class="day-row" role="row"><span class="day-label" role="rowheader">{lane.day.slice(8)}.{lane.day.slice(5,7)}</span><div class="day-lane" role="gridcell"><div class="empty-band"></div>{#each ticks as tick}<i class="time-grid" style:left={`${tick.left*100}%`}></i>{/each}
{#each lane.clips.filter(piece=>piece.right>=view.start&&piece.left<=view.end) as piece}{@const key=rowKey(piece.row)}{@const state=rowState(piece.row)}<button type="button" class="timeline-clip" class:gap={piece.row.timeline_state==='gap'} class:selected={active.has(key)} class:hovered={hovered.includes(key)} style:left={`${Math.max(0,(piece.left-view.start)/span)*100}%`} style:width={`${Math.max(.15,(Math.min(view.end,piece.right)-Math.max(view.start,piece.left))/span*100)}%`} style:background={state.colour} data-keys={JSON.stringify([key])} aria-label={describe(piece.row)} aria-pressed={active.has(key)} onclick={event=>{if(event.detail===0)choose([key],multi);}}></button>{/each}
{#each clusterMarkers(lane.markers.filter(marker=>marker.left>=view.start&&marker.left<=view.end).map(marker=>({...marker,left:(marker.left-view.start)/span})),width) as cluster}{@const markerRows=cluster.rows as TimelineRow[]}{@const keys=markerRows.map(rowKey)}{@const representative=markerRows.find(row=>row.availability_kind==='booking')??markerRows.find(row=>row.availability_kind==='office')??markerRows[0]}{@const state=rowState(representative)}<button type="button" class="timeline-marker" class:selected={keys.some(key=>active.has(key))} class:hovered={keys.some(key=>hovered.includes(key))} style:left={`${cluster.left*100}%`} style:color={state.colour} style:width={`${Math.max(24,markerTypes(markerRows).length*20+4)}px`} data-keys={JSON.stringify(keys)} aria-label={markerRows.map(describe).join('; ')} aria-pressed={keys.some(key=>active.has(key))} onclick={event=>{if(event.detail===0)choose(keys,multi);}}><span class="marker-icons">{#each markerTypes(markerRows) as type}<span style:color={rowState(type).colour}><Icon name={rowState(type).icon} size={17}/></span>{/each}</span>{#if markerRows.length>1}<small>{markerRows.length}</small>{/if}</button>{/each}
</div></div>{/each}
{#if skimmer!==null&&!drag}<div class="skimmer" style:left={`${56+skimmer*width}px`}><span>{hoverClock}</span></div>{/if}
</div>{/if}
{#if tooltip&&!drag}<div class="timeline-tooltip" style:left={`${tooltipAt.left}px`} style:top={`${tooltipAt.top}px`}>{tooltip}</div>{/if}
{#if selected.length}<article class="selection-detail"><div class="selection-heading"><h3><Icon name={selectedRows.length===1?rowState(selectedRows[0]).icon:'list'}/>{selectedRows.length===1?t(rowState(selectedRows[0]).label):t('Выбрано участков: {count}').replace('{count}',String(selected.length))}</h3><button class="icon-button" title={t('Сбросить выделение')} aria-label={t('Сбросить выделение')} onclick={clear}><Icon name="close"/></button></div>{#if summaryLoading}<p class="muted" role="status">{t('Загрузка статистики…')}</p>{:else if summaryFailed}<p class="error" role="alert">{t('Не удалось прочитать статистику выбранных участков')}</p>{:else if summary}<div class="selection-times"><div><small>{t('Начало')}</small><strong>{stamp(summary.start,language)}</strong></div><div><small>{t('Конец')}</small><strong>{stamp(summary.end,language)}</strong></div><div><small>{t('Длительность')}</small><strong>{observedDuration(summary.seconds,language,t)}</strong></div></div><div class="selection-metrics">{#each metrics as [key,label]}<div><span>{t(label)}</span><strong>{new Intl.NumberFormat(language).format(summary.counts[key]??0)}</strong></div>{/each}</div>{#if summary.gap_seconds>0}<p class="muted">{t('Нет наблюдений')}: {observedDuration(summary.gap_seconds,language,t)}</p>{/if}{#if summary.restored_seconds>0}<p class="muted">{t('Восстановлено по журналам запуска')}: {observedDuration(summary.restored_seconds,language,t)}</p>{/if}{#if summary.offices.length}<div class="selection-offices">{#each summary.offices as office}<span>{office}</span>{/each}</div>{/if}{#each selectedRows.filter(row=>row.bookings?.length) as row}<p class="booking-details">{bookingLines(row)}</p>{/each}{/if}</article>{/if}
</section>
<style>
.timeline{--selected:#f1c65a;position:relative}.timeline-tools{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:16px}.timeline-tools .flat{border:0;background:none;padding:6px 8px;min-height:32px}.timeline-tools .chosen{color:var(--accent-text);background:var(--selection)}.tools-spacer{flex:1}.legend-dots{display:flex;gap:3px}.legend-dots i{width:5px;height:12px;border-radius:1px}.timeline-legend{display:flex;flex-wrap:wrap;gap:10px 18px;color:var(--muted);font-size:12px;margin-bottom:20px}.timeline-legend span{display:flex;align-items:center;gap:6px}.timeline-legend i{display:inline-block;width:12px;height:10px;border:1px solid var(--line)}.time-axis{position:relative;height:25px;margin-left:56px;margin-right:10px;font-size:11px;font-variant-numeric:tabular-nums;color:var(--muted)}.time-axis span{position:absolute;transform:translateX(-50%);white-space:nowrap}.time-axis span.first{transform:none}.time-axis span.last{transform:translateX(-100%)}.timeline-board{position:relative;user-select:none;touch-action:pan-y;margin-right:10px}.timeline-board:focus{outline:none}.day-row{height:46px;display:grid;grid-template-columns:56px minmax(0,1fr)}.day-label{color:var(--muted);font-size:12px;padding-top:25px;font-variant-numeric:tabular-nums}.day-lane{position:relative;min-width:0}.empty-band{position:absolute;top:26px;left:0;right:0;height:14px;background:repeating-linear-gradient(130deg,transparent,transparent 3px,var(--line) 3px,var(--line) 4px);opacity:.6}.time-grid{position:absolute;top:0;bottom:0;width:1px;background:var(--line);opacity:.45;pointer-events:none}.timeline-clip{position:absolute;top:26px;height:14px;min-height:14px;border:0;border-radius:1px;padding:0;min-width:1px;z-index:1}.timeline-clip.gap,.timeline-legend .gap{background:repeating-linear-gradient(130deg,transparent,transparent 3px,var(--line) 3px,var(--line) 4px)!important}.timeline-clip:hover,.timeline-clip.hovered{filter:brightness(1.25);outline:1px solid var(--text);outline-offset:1px;z-index:2}.timeline-clip.selected{outline:2px solid var(--selected);outline-offset:2px;z-index:3}.timeline-clip.selected::before,.timeline-clip.selected::after{content:'';position:absolute;top:-5px;bottom:-5px;width:2px;background:var(--selected)}.timeline-clip.selected::before{left:-3px}.timeline-clip.selected::after{right:-3px}.timeline-marker{position:absolute;top:0;transform:translateX(-50%);width:24px;height:25px;min-height:25px;padding:2px;border:0;border-radius:4px;background:var(--bg);z-index:4;overflow:visible}.timeline-marker::after{content:'';position:absolute;top:23px;height:16px;width:1px;background:currentColor;left:50%;pointer-events:none}.timeline-marker.selected,.timeline-marker:hover,.timeline-marker.hovered{outline:2px solid var(--selected);outline-offset:1px;background:var(--surface)}.marker-icons{display:flex;align-items:center;gap:3px}.marker-icons>span{display:flex}.timeline-marker small{position:absolute;right:-5px;top:-4px;border-radius:8px;background:var(--surface);color:var(--text);font-size:9px;padding:0 3px;line-height:13px}.skimmer{position:absolute;top:-7px;bottom:0;width:1px;background:var(--text);z-index:8;pointer-events:none}.skimmer span{position:absolute;left:0;top:-22px;transform:translateX(-50%);border-radius:4px;padding:2px 5px;color:var(--bg);background:var(--text);font:11px PlexMono,monospace;white-space:nowrap}.timeline-tooltip{position:fixed;z-index:20;padding:10px 12px;max-width:320px;max-height:180px;overflow:hidden;white-space:pre-line;border:1px solid var(--strong);border-radius:7px;background:var(--surface);color:var(--text);font-size:12px;box-shadow:0 8px 20px #0003;pointer-events:none}.selection-detail{padding:16px 18px;margin-top:20px;background:var(--surface);border:1px solid var(--line);border-radius:8px}.selection-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.selection-heading h3{font-size:15px;display:flex;align-items:center;gap:8px;margin:0;font-weight:600}.selection-times{display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px;padding-bottom:14px;border-bottom:1px solid var(--line)}.selection-times small{display:block;color:var(--muted);margin-bottom:5px}.selection-times strong{font-weight:400;font-variant-numeric:tabular-nums}.selection-metrics{display:grid;grid-template-columns:1fr 1fr;gap:12px 26px;margin-top:16px}.selection-metrics>div{display:flex;align-items:center;justify-content:space-between;gap:10px}.selection-metrics span{color:var(--muted)}.selection-metrics strong{font-weight:600;font-variant-numeric:tabular-nums}.selection-offices{display:grid;gap:6px;border-top:1px solid var(--line);padding-top:12px;margin-top:12px}.booking-details{white-space:pre-line}.timeline-empty{padding:24px 0}@media(max-width:750px){.timeline-tools{gap:2px}.timeline-tools .flat{font-size:12px;padding:6px}.selection-times{grid-template-columns:1fr 1fr}.selection-metrics{gap:10px 20px}}
</style>
